    private CharSequence iconLabel(int code,String label){
        android.text.SpannableString result=new android.text.SpannableString(String.valueOf((char)code)+(label.isEmpty()?"":"  "+label));
        result.setSpan(new android.text.style.MetricAffectingSpan(){
            public void updateDrawState(android.text.TextPaint p){p.setTypeface(iconFont);}
            public void updateMeasureState(android.text.TextPaint p){p.setTypeface(iconFont);}
        },0,1,android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);return result;
    }
    private CharSequence buttonLabel(String label){
        if(label.equals("⋯"))return iconLabel(0xe1fe,"");
        if(label.startsWith("‹ "))return iconLabel(0xe138,label.substring(2));
        if(label.startsWith("＋"))return iconLabel(0xe3d4,label.substring(1).trim());
        if(label.startsWith("⌄"))return iconLabel(0xe136,label.substring(1).trim());
        if(label.startsWith("⌃"))return iconLabel(0xe13c,label.substring(1).trim());
        if(label.startsWith("记录曝光 "))return iconLabel(0xe10e,label);
        if(label.startsWith("保存曝光 "))return iconLabel(0xe10e,label);
        if(label.equals("保存修改"))return iconLabel(0xe182,label);
        if(label.equals("编辑曝光"))return iconLabel(0xe3b4,label);
        if(label.equals("定位权限 / 设置"))return iconLabel(0xe316,label);
        return label;
    }
