        for(int i=0;i<Math.min(rollShotLimit,shotMatches.size());i++){
            LogStore.Shot s=store.shot(shotMatches.get(i));LogStore.Roll r=rolls.get(s.rollId);String date=Instant.ofEpochMilli(s.captured).atOffset(ZoneOffset.ofTotalSeconds(s.zone*60)).toLocalDate().toString();
            if(!date.equals(day)){day=date;TextView label=text(day,11,getColor(R.color.ui_muted));label.setPadding(0,dp(i==0?4:20),0,dp(10));rollResults.addView(label);}
            LinearLayout card=card(),line=row();card.setTag("roll-shot-result:"+s.id);TextView frame=heading(String.format(Locale.CHINA,"%02d",s.frame),22);frame.setTextColor(getColor(R.color.ui_accent));line.addView(frame,new LinearLayout.LayoutParams(dp(40),-2));LinearLayout words=column();TextView title=heading(s.memo.isEmpty()?"拍摄记录":s.memo,14);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(title);words.addView(text(r.stock+" · "+r.camera,11,getColor(R.color.ui_muted)));String params=(s.aperture.isEmpty()?"":ExposureChoices.apertureLabel(s.aperture))+(s.shutter.isEmpty()?"":(s.aperture.isEmpty()?"":" · ")+s.shutter);if(!params.isEmpty())words.addView(text(params,12,getColor(R.color.ui_ink)));words.addView(text(format(s.captured,s.zone).substring(11)+" · "+r.name,11,getColor(R.color.ui_muted)));line.addView(words,new LinearLayout.LayoutParams(0,-2,1));line.addView(text("›",20,getColor(R.color.ui_muted)));card.addView(line);card.setFocusable(true);card.setContentDescription("曝光 "+s.frame+"，"+r.name+"，"+(s.memo.isEmpty()?"拍摄记录":s.memo));card.setOnClickListener(v->{hideKeyboard();rememberRollList();rollSearchDetail=true;rollBackScreen="home";rollId=r.id;shotId=s.id;screen="detail";render();});LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(-1,-2);size.bottomMargin=dp(8);rollResults.addView(card,size);
        }
        if(shotMatches.size()>rollShotLimit){Button load=rollAction("加载更多曝光 · 还有 "+(shotMatches.size()-rollShotLimit)+" 张",()->{int y=pageScroll.getScrollY();rollShotLimit+=100;renderRollResults();pageScroll.post(()->pageScroll.scrollTo(0,y));});load.setTag("roll-load-shots");rollResults.addView(load);}
