            String id=reference.isEmpty()?store.recordLocated(draft.getString("request"),boundRoll,tap,delta,zone,"","","","","","",fix):ReferencePhotos.record(this,store,reference,boundRoll,tap,delta,zone,"acquired",draft.getString("aperture",""),draft.getString("shutter",""),"",draft.getString("memo",""),"","",fix);
