    private void rollActions(LogStore.Roll r){
        rollId=r.id;
        LinearLayout content=column();rollSummary(content,r);final Dialog[] dialog={null};
        if(!r.archived){if(r.state.equals("active"))menuAction(content,finishAction(r),false,()->{dialog[0].dismiss();rewind(r);});else if(r.state.equals("finished")){menuAction(content,"送去冲洗",false,()->{dialog[0].dismiss();sendToLab(r);});menuAction(content,"纠正结束标记",false,()->{dialog[0].dismiss();confirmState(r,"active","纠正结束标记？","仅用于误标且实际尚未结束拍摄的情况。已经回卷或取出的胶片不能直接继续拍摄。");});}else{menuAction(content,"编辑冲洗信息",false,()->{dialog[0].dismiss();labForm(r,"edit");});if(r.state.equals("developing"))menuAction(content,"撤销送洗",false,()->{dialog[0].dismiss();confirmState(r,"finished","撤销这次送洗？","这卷将退回待送洗。已有曝光和费用保留。");});}}
        if(screen.equals("home"))menuAction(content,"选择多卷",false,()->{dialog[0].dismiss();enterRollSelection(r);});
        menuAction(content,"制作分享图",false,()->{dialog[0].dismiss();startActivity(new Intent(this,SharePosterActivity.class).putExtra("roll",r.id));});
        menuAction(content,"编辑胶卷资料",false,()->{dialog[0].dismiss();rollForm(r);});menuAction(content,"增减感与费用",false,()->{dialog[0].dismiss();rollSettings(r);});String artwork=ArtworkLinks.get(store,"roll",r.id);if(!artwork.isEmpty())menuAction(content,"查看片种资料",false,()->{dialog[0].dismiss();startActivity(new Intent(this,StockDetailActivity.class).putExtra("stock",artwork));});CatalogStore.Detail inventory=new CatalogStore(store).detail(r.id);
        if(inventory!=null&&!inventory.batch.isEmpty()&&!inventory.returned&&!r.archived&&r.state.equals("active")&&r.count==0)menuAction(content,"撤销装卷并返还库存",false,()->{dialog[0].dismiss();new AlertDialog.Builder(this).setTitle("撤销空卷装卷？").setMessage("返还1卷库存，空卷记录归档保留。").setNegativeButton("取消",null).setPositiveButton("返还库存",(d,w)->{try{new CatalogStore(store).returnUnused(r.id);showRoll();}catch(Exception e){toast(e.getMessage());}}).show();});
        if(!r.state.equals("received")&&(inventory==null||!inventory.returned))menuAction(content,r.archived?"恢复归档":"归档胶卷",false,()->{dialog[0].dismiss();setArchived(r,!r.archived);});space(content,12);menuAction(content,"删除胶卷",true,()->{dialog[0].dismiss();confirmDeleteRoll(r);});dialog[0]=bottomSheet("胶卷操作",content);
    }
