    private void customExposure(boolean isAperture){
        captureDraft();int position=pageScroll.getScrollY();LinearLayout form=column();form.setPadding(dp(20),dp(8),dp(20),dp(12));
        EditText value=input(form,isAperture?"光圈 f/（0.7–256）":"快门秒数或分数（例如1/90、2.5s）",isAperture?aperture:shutter,isAperture?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT);
        auxiliaryDraft(isAperture?"aperture":"shutter",rollId,value);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(isAperture?"自定义光圈":"自定义快门").setView(form).setNegativeButton("取消",(d,w)->clearAuxiliaryDraft()).setPositiveButton("应用到草稿",null).create();dialog.setOnCancelListener(d->clearAuxiliaryDraft());
        dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{String normalized;if(isAperture)normalized=PhotoMath.apertureValue(value.getText().toString());else{double seconds=PhotoMath.seconds(value.getText().toString());normalized=PhotoMath.shutterChoice(seconds);}captureDraft();draft.remove("preset");draft.putString(isAperture?"aperture":"shutter",normalized);clearAuxiliaryDraft();dialog.dismiss();hideKeyboard();showEditor();pageScroll.post(()->pageScroll.scrollTo(0,position));}catch(IllegalArgumentException error){value.setError(error.getMessage());}}));dialog.show();
    }
