    private void saveExposure(){
        if(saving)return;long tap=draft!=null&&draft.containsKey("recordTap")?draft.getLong("recordTap"):System.currentTimeMillis();int delta;try{delta=RecordRules.parseOffset(offset.getText().toString());}catch(IllegalArgumentException e){offset.setError("请输入 −3600 到 +3600 的整数秒");return;}captureDraft();
        if(shotId.isEmpty()){draft.putLong("recordTap",tap);if(!draft.containsKey("recordZone"))draft.putInt("recordZone",TimeZone.getDefault().getOffset(RecordRules.captureTime(tap,delta))/60000);if(!draft.containsKey("request"))draft.putString("request",UUID.randomUUID().toString());if(!ensureRecordLocation("editor"))return;}
        saving=true;String id=shotId;
        try{
            if(id.isEmpty()){int zone=draft.getInt("recordZone");String reference=draft.getString("referenceToken","");Location fix=new Location(latest);if(reference.isEmpty())id=store.recordLocated(draft.getString("request"),rollId,tap,delta,zone,aperture,shutter,lens.getText().toString(),draft.getString("memo",""),ev.getText().toString(),filters.getText().toString(),fix);else id=ReferencePhotos.record(this,store,reference,rollId,tap,delta,zone,"acquired",aperture,shutter,lens.getText().toString(),draft.getString("memo",""),ev.getText().toString(),filters.getText().toString(),fix);}
            else store.edit(store.shot(id),delta,aperture,shutter,lens.getText().toString(),draft.getString("memo",""),ev.getText().toString(),filters.getText().toString());
        }catch(Exception e){saving=false;clearLocationGate();toast(e instanceof IllegalArgumentException?e.getMessage():"保存失败，记录未清除，请重试");return;}
        getPreferences(0).edit().putInt("offset",delta).apply();hideKeyboard();boolean isNew=shotId.isEmpty(),returnDashboard=draft!=null&&draft.getBoolean("returnDashboard",false)&&draft.getString("referenceToken","").isEmpty();if(isNew)clearPendingAfterSave();clearLocationGate();draft=null;screen=isNew?(returnDashboard?"dashboard":"roll"):"detail";if(!isNew)shotId=id;saving=false;
        render();toast(isNew?"曝光与定位已保存":"修改已保存");
    }
    private String detailSettings(LogStore.Shot shot){ArrayList<String> values=new ArrayList<>();if(!shot.aperture.isEmpty())values.add(ExposureChoices.apertureLabel(shot.aperture));if(!shot.shutter.isEmpty())values.add(shot.shutter);if(!shot.lens.isEmpty())values.add(shot.lens);return values.isEmpty()?"":android.text.TextUtils.join(" · ",values)+" · ";}
