    @Override public void onBackPressed(){if(screen.equals("editor"))cancelEditor();else if(screen.equals("detail")){if(rollSearchDetail){rollSearchDetail=false;screen="home";render();}else openRoll(rollId);}else if(screen.equals("created"))finishCreated();else if(screen.equals("roll"))returnFromRoll();else if(screen.equals("settings"))returnFromSettings();else if(screen.equals("data")){screen="my";render();}else if(screen.equals("tools")){screen="dashboard";render();}else if(screen.equals("permissions")){screen="settings";render();}else if(screen.equals("my")){screen="dashboard";render();}else if(screen.equals("home")){if(rollSelecting)exitRollSelection();else if(rollSearchActive)cancelRollSearch();else{screen="dashboard";render();}}else super.onBackPressed();}
