    private static String format(long time,int zone){return TIME.format(Instant.ofEpochMilli(time).atOffset(ZoneOffset.ofTotalSeconds(zone*60)));}
    private static String stateLabel(String state){switch(state){case "pending":return "正在定位";case "denied":return "未授权定位";case "disabled":return "定位关闭或不可用";case "timeout":return "定位超时";case "interrupted":return "定位未完成";default:return "未记录位置";}}
    @Override protected void onSaveInstanceState(Bundle b){rememberRollList();b.putBundle("rollCriteria",rollCriteria.save());b.putBoolean("rollSearchActive",rollSearchActive);b.putBoolean("rollShots",rollShots);b.putBoolean("rollSelecting",rollSelecting);b.putBoolean("rollArchiveTarget",rollArchiveTarget);b.putBoolean("rollSearchDetail",rollSearchDetail);b.putInt("rollShotLimit",rollShotLimit);b.putInt("rollBeforeSelectionScroll",rollBeforeSelectionScroll);b.putBundle("rollFilterDraft",rollFilterDraft);Bundle chosen=new Bundle();for(Map.Entry<String,String> e:rollSelected.entrySet())chosen.putString(e.getKey(),e.getValue());b.putBundle("rollSelected",chosen);b.putInt("rollScrollY",rollScrollY);b.putInt("rollArchiveLimit",rollArchiveLimit);b.putString("rollTargetGroup",rollTargetGroup);captureDraft();if(rollDraft!=null&&rollInputs!=null)for(int k=0;k<rollInputs.length;k++)rollDraft.putString("field"+k,rollInputs[k].getText().toString());b.putInt("createdReminder",createdReminder);b.putInt("pendingReminder",pendingReminder);b.putBundle("presetDraft",presetDraft);b.putString("artworkOwner",artworkOwner);b.putBundle("rollDraft",rollDraft);if(auxDraft!=null&&auxInputs!=null)for(int i=0;i<auxInputs.length;i++)auxDraft.putString("field"+i,auxInputs[i].getText().toString());b.putBundle("auxDraft",auxDraft);b.putString("rollFilter",rollFilter);b.putString("rollQuery",rollQuery);b.putString("rollBackScreen",rollBackScreen);b.putString("settingsBackScreen",settingsBackScreen);b.putString("pendingMeterRoll",pendingMeterRoll);b.putString("screen",screen);b.putString("roll",rollId);b.putString("shot",shotId);b.putBundle("draft",draft);super.onSaveInstanceState(b);}
    private boolean allowed(){return checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
    private void enableLocation(){
        if(!allowed()){
            if(getPreferences(0).getBoolean("asked",false)&&!shouldShowRequestPermissionRationale(Manifest.permission.ACCESS_COARSE_LOCATION)){startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName())));return;}
            new AlertDialog.Builder(this).setTitle("记录拍摄地点").setMessage("仅在应用前台获取位置。新曝光取得有效位置后才保存；未授权时保留未保存草稿，不会产生无定位记录。")
                .setPositiveButton("继续",(d,w)->{getPreferences(0).edit().putBoolean("asked",true).apply();requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},1);}).setNegativeButton("暂不开启",null).show();
        }else startActivity(new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS));
    }
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==1){ForegroundLocation.get(this).refresh(true);startLocation();resumeRecordAttempt();}else if(r==73){int choice=pendingReminder;pendingReminder=-1;if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&screen.equals("created")&&choice>=0)chooseCreatedReminder(choice);else toast("未设置提醒，曝光记录仍可正常使用");}}
    private boolean hasResumed;
    @Override protected void onResume(){super.onResume();boolean refreshPage=hasResumed;hasResumed=true;ExposureReminders.restore(this);try{if(ExposureClock.needsService(this))startForegroundService(new Intent(this,ExposureTimerService.class));}catch(Exception error){toast("计时后台服务未恢复，请打开计时页核对："+error.getMessage());}resumed=true;ExposureWidget.updateAll(this);if(root!=null){startLocation();if(draft!=null&&"editor".equals(draft.getString("locationAction",""))){saveExposure();return;}if(draft!=null&&draft.getBoolean("newRecord",false)){commitNewRecord();return;}if(screen.equals("created")&&refreshCreated!=null)refreshCreated.run();if(screen.equals("editor")&&draft!=null&&draft.getBoolean("saveOnResume",false)){draft.putBoolean("saveOnResume",false);saveExposure();return;}if(refreshPage&&(Arrays.asList("home","dashboard","my","settings","permissions","data","tools").contains(screen)||((screen.equals("roll")||screen.equals("detail"))&&rollDraft==null&&auxDraft==null)))render();}}
    @Override protected void onPause(){resumed=false;clearLocationGate();if(draft!=null)draft.remove("locationConfirmed");stopLocation();super.onPause();}
    @Override protected void onDestroy(){if(existingEditor!=null)existingEditor.dispose();stopLocation();if(rollDatePicker!=null)rollDatePicker.dismiss();if(rollSheet!=null)rollSheet.dismiss();handler.removeCallbacksAndMessages(null);if(store!=null)store.close();super.onDestroy();}
    private void startLocation(){if(!resumed)return;ForegroundLocation shared=ForegroundLocation.get(this);shared.add(locationObserver);locationObserver.changed();}
    private void stopLocation(){ForegroundLocation.get(this).remove(locationObserver);watching=false;}
    private boolean usable(Location l){return ForegroundLocation.usable(l);}
    private String locationLabel(){if(!allowed())return "开启定位后才能记录  ›";if(usable(latest)){long age=SystemClock.elapsedRealtime()-latest.getElapsedRealtimeNanos()/1000000;return age<=RecordRules.MAX_FIX_AGE_MS?String.format(Locale.CHINA,"定位就绪 · 精度约 %.0f 米",latest.getAccuracy()):String.format(Locale.CHINA,"近期定位 · %d秒前 · 精度约 %.0f 米",age/1000,latest.getAccuracy());}if(!watching)return "打开系统定位后才能记录  ›";return ForegroundLocation.get(this).status()==ForegroundLocation.Status.UPDATING?"正在更新定位 · 取得位置后可记录":"暂未取得定位 · 正在持续重试";}
    private void updateGps(){ForegroundLocation.Status status=ForegroundLocation.get(this).status();if(homeLocation!=null){String label=status==ForegroundLocation.Status.READY?"定位就绪":status==ForegroundLocation.Status.UPDATING?"正在更新":"无定位";homeLocation.setText(label);((View)homeLocation.getParent()).setContentDescription(label);GradientDrawable dot=new GradientDrawable();dot.setShape(GradientDrawable.OVAL);dot.setColor(getColor(status==ForegroundLocation.Status.READY?R.color.ui_green:status==ForegroundLocation.Status.UPDATING?R.color.ui_location_updating:R.color.ui_error));homeLamp.setBackground(dot);}if(gps!=null){gps.setText(locationLabel());gps.setTextColor(getColor(status==ForegroundLocation.Status.UPDATING?R.color.ui_location_updating:status==ForegroundLocation.Status.READY?R.color.ui_green:R.color.ui_error));gps.setContentDescription("定位权限与状态，"+locationLabel());}}
    private boolean locationTimeConfirmed(){return draft!=null&&PendingExposure.matches(this,draft,latest);}
    private boolean checkpointPending(String action){
        if(draft==null)return false;
        try{if(!draft.getBoolean("newRecord",false))captureDraft();if(!draft.containsKey("recordRoll"))draft.putString("recordRoll",rollId);if(!draft.containsKey("request"))draft.putString("request",UUID.randomUUID().toString());PendingExposure.inferLegacyTime(this,draft);draft.putString("locationAction",action);String page=draft.getBoolean("newRecord",false)?(draft.getBoolean("quick",false)?draft.getString("returnScreen","dashboard"):"roll"):"editor";PendingExposure.save(this,draft,page);draft.putBoolean("pendingPersisted",true);return true;}
        catch(Exception error){clearLocationGate();if(resumed)new AlertDialog.Builder(this).setTitle("待定位草稿未能保留").setMessage("曝光尚未保存，已有资料没有清除。\n"+error.getMessage()).setPositiveButton("重试",(d,w)->resumeRecordAttempt()).setNegativeButton("取消本次记录",(d,w)->cancelLocatedRecord()).setCancelable(false).show();else toast("待定位草稿未能保留，返回后请核对");return false;}
    }
    private void clearPendingAfterSave(){try{PendingExposure.clear(this);}catch(IOException error){toast("曝光已保存；待定位草稿清理失败，重开会自动核对，勿重复记录");}}
    private boolean ensureRecordLocation(String action){
        if(draft==null||!resumed||!checkpointPending(action))return false;startLocation();
        if(allowed()&&watching&&!usable(latest))ForegroundLocation.get(this).refresh(true);
        if(allowed()&&locationTimeConfirmed())return true;
        showLocationGate();
        if(!locationWaiting){locationWaiting=true;locationTimeout=()->{locationTimeout=null;if(draft!=null){draft.putBoolean("locationTimedOut",true);showLocationGate();}};handler.postDelayed(locationTimeout,RecordRules.WAIT_MS);}
        return false;
    }
    private void showLocationGate(){
        if(!resumed||draft==null)return;
        String message,action;
        if(!allowed()){message="尚未授权定位。这张曝光尚未保存，点击时间已保留。允许定位后才能完成记录。";action="开启定位";}
        else if(!watching){message="系统定位未开启或不可用。这张曝光尚未保存，请打开定位后返回。";action="定位设置";}
        else if(PendingExposure.needsConfirmation(this,draft)){message=(usable(latest)?"已取得当前位置，但尚不能确认与原拍摄时刻匹配。":"仍在自动获取与原拍摄时刻匹配的位置。")+"草稿已保留，不会把后来异地的位置填入这张曝光。如果仍在原拍摄地点，可确认后使用自动取得的位置；原拍摄时间保持不变。";action="仍在原拍摄地点";}
        else if(draft.getBoolean("locationTimedOut",false)){message="仍在自动定位，草稿已保留。取得与拍摄时刻匹配的位置后会自动完成，不需要反复点击重试。";action="刷新定位";}
        else{message="正在自动获取位置，草稿已保留。取得匹配位置后会自动完成，拍摄时间仍是刚才点击的时刻。";action="刷新定位";}
        if(locationDialog==null){locationDialog=new AlertDialog.Builder(this).setTitle("为这张曝光记录定位").setMessage(message).setNegativeButton("取消本次记录",(d,w)->cancelLocatedRecord()).setPositiveButton(action,null).setCancelable(false).create();AlertDialog shown=locationDialog;shown.setOnShowListener(d->{if(locationDialog==shown)shown.getButton(-1).setOnClickListener(v->retryRecordLocation());});shown.show();}
        else{locationDialog.setMessage(message);locationDialog.getButton(-1).setText(action);}
    }
    private void retryRecordLocation(){
        if(draft==null)return;
        if(!allowed()){clearLocationGate();enableLocation();return;}
        if(!watching){clearLocationGate();startActivity(new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS));return;}
        if(PendingExposure.needsConfirmation(this,draft))PendingExposure.confirmHere(this,draft);
        draft.remove("locationTimedOut");clearLocationGate();ForegroundLocation.get(this).refresh(true);resumeRecordAttempt();
    }
    private void resumeRecordAttempt(){if(!resumed||draft==null)return;String action=draft.getString("locationAction","");if(action.equals("new"))commitNewRecord();else if(action.equals("editor"))saveExposure();}
    private void resumeLocatedAction(){if(resumed&&locationWaiting&&draft!=null&&allowed()&&locationTimeConfirmed())resumeRecordAttempt();}
    private void clearLocationGate(){locationWaiting=false;if(locationTimeout!=null)handler.removeCallbacks(locationTimeout);locationTimeout=null;if(locationDialog!=null){locationDialog.dismiss();locationDialog=null;}}
    private void cancelLocatedRecord(){try{PendingExposure.clear(this);}catch(IOException error){toast("草稿未能取消，仍保留："+error.getMessage());return;}clearLocationGate();if(draft!=null){if(draft.getBoolean("newRecord",false)){ReferencePhotos.discard(this,draft.getString("referenceToken",""));draft=null;}else{draft.remove("locationAction");draft.remove("locationTimedOut");draft.remove("locationConfirmed");draft.remove("pendingPersisted");}}render();}
    private void export(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/csv");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"胶片随记-"+LocalDate.now()+".csv");try{startActivityForResult(i,2);}catch(ActivityNotFoundException e){toast("没有可用的文件保存器");}}
    @Override protected void onActivityResult(int req,int result,Intent data){
        super.onActivityResult(req,result,data);if(req==21&&result==RESULT_OK&&data!=null&&screen.equals("editor")&&!shotId.isEmpty()&&draft!=null){
            draft.remove("preset");for(String field:new String[]{"aperture","shutter","ev"})if(data.hasExtra(field)){String v=data.getStringExtra(field);if(v!=null&&!v.isEmpty())draft.putString(field,v);}if(data.hasExtra("ev100"))draft.putDouble("meterEV",data.getDoubleExtra("ev100",15));if(data.hasExtra("filter_note")){String note=data.getStringExtra("filter_note");if(note!=null&&!note.isEmpty()){String old=draft.getString("filters","");draft.putString("filters",old.isEmpty()?note:old+"; "+note);}}showEditor();return;
        }if(req==25){if(result==RESULT_OK&&data!=null&&!artworkOwner.isEmpty())try{ArtworkLinks.set(this,store,"roll",artworkOwner,data.getStringExtra("stock"));render();}catch(Exception error){toast(error.getMessage());}artworkOwner="";return;}if(req==24){if(result==RESULT_OK&&data!=null&&rollDraft!=null&&rollWizard!=null)try{rollWizard.useStock(data.getStringExtra("stock"),data.getIntExtra("stock_iso",0));}catch(Exception error){toast(error.getMessage());}return;}if(req==23){if(!pendingMeterRoll.isEmpty())rollId=pendingMeterRoll;pendingMeterRoll="";if(result==RESULT_OK&&data!=null&&data.getBooleanExtra("record_meter",false)){draft=new Bundle();draft.putBoolean("newRecord",true);draft.putString("recordRoll",rollId);draft.putString("referenceToken",data.getStringExtra("reference_token"));draft.putLong("recordTap",data.getLongExtra("record_tap",0));if(data.hasExtra("record_elapsed")){draft.putLong("recordElapsed",data.getLongExtra("record_elapsed",-1));draft.putInt("recordBoot",data.getIntExtra("record_boot",-1));draft.putString("recordProcess",data.getStringExtra("record_process"));}draft.putInt("recordZone",data.getIntExtra("record_zone",0));draft.putString("offset",String.valueOf(data.getIntExtra("record_delta",RecordRules.DEFAULT_OFFSET)));draft.putString("aperture",data.getStringExtra("aperture"));draft.putString("shutter",data.getStringExtra("shutter"));draft.putString("memo",PhotoMath.meterMemo("",data.getIntExtra("meter_iso",400)));if(checkpointPending("new")&&resumed)commitNewRecord();}return;}if(req==22&&result==RESULT_OK&&data!=null){String destination=data.getStringExtra("main_tab");if(destination!=null&&Arrays.asList("dashboard","home","my").contains(destination)){screen=destination;render();return;}String selected=data.getStringExtra("roll");if(selected!=null){rollFilter="active";if(data.getBooleanExtra("created_roll",false))reminderOffer(selected);else openRoll(selected);}return;}if(req==21&&result==RESULT_OK&&data!=null&&screen.equals("editor")&&draft!=null){draft.remove("preset");if(data.hasExtra("ev100"))draft.putDouble("meterEV",data.getDoubleExtra("ev100",0));else draft.remove("meterEV");for(String key:new String[]{"aperture","shutter","ev"})if(data.hasExtra(key))draft.putString(key,data.getStringExtra(key));if(data.getBooleanExtra("record_meter",false)&&shotId.isEmpty()){String old=draft.getString("referenceToken","");String token=data.getStringExtra("reference_token");if(!old.equals(token))ReferencePhotos.discard(this,old);draft.putString("referenceToken",token);draft.putLong("recordTap",data.getLongExtra("record_tap",0));if(data.hasExtra("record_elapsed")){draft.putLong("recordElapsed",data.getLongExtra("record_elapsed",-1));draft.putInt("recordBoot",data.getIntExtra("record_boot",-1));draft.putString("recordProcess",data.getStringExtra("record_process"));}draft.putInt("recordZone",data.getIntExtra("record_zone",0));draft.putString("offset",String.valueOf(data.getIntExtra("record_delta",RecordRules.DEFAULT_OFFSET)));draft.putBoolean("saveOnResume",true);}if(data.getBooleanExtra("record_meter",false)&&data.hasExtra("meter_iso"))draft.putString("memo",PhotoMath.meterMemo(draft.getString("memo",""),data.getIntExtra("meter_iso",400)));if(data.hasExtra("filter_note")){String old=draft.getString("filters","");draft.putString("filters",old.isEmpty()?data.getStringExtra("filter_note"):old+"; "+data.getStringExtra("filter_note"));}showEditor();return;}if(req==20&&result==RESULT_OK&&data!=null){if(screen.equals("home"))rollBackScreen="home";rollId=data.getStringExtra("roll");shotId=data.getStringExtra("shot");screen=shotId==null||shotId.isEmpty()?"roll":"detail";draft=null;render();return;}if(req!=2||result!=RESULT_OK||data==null||data.getData()==null)return;
        String[] columns={"id","roll_name","stock","camera","iso","frame_number","aperture","shutter","lens","ev","filters","memo","tapped_at","captured_at","offset_seconds","zone_offset_minutes","status","latitude","longitude","accuracy_m","location_time","provider","roll_state","roll_archived","lab","lab_number","lab_cost","roll_id","roll_capacity","film_cost","cost_currency","lab_sent_date","lab_received_date","lab_notes","time_edited"};
        try(OutputStream stream=getContentResolver().openOutputStream(data.getData());Writer w=new OutputStreamWriter(stream,StandardCharsets.UTF_8);Cursor c=store.exportRows()){
            w.write('\ufeff');w.write(String.join(",",columns).replace("tapped_at","tapped_at_utc").replace("captured_at","captured_at_utc").replace("location_time","location_time_utc"));w.write("\r\n");
            while(c.moveToNext()){for(int i=0;i<columns.length;i++){if(i>0)w.write(',');String col=columns[i],s=LogStore.str(c,col);if(!s.isEmpty()&&(col.equals("tapped_at")||col.equals("captured_at")||col.equals("location_time")))s=Instant.ofEpochMilli(Long.parseLong(s)).toString();w.write('"');w.write(s.replace("\"","\"\""));w.write('"');}w.write("\r\n");}w.flush();toast("已导出全部胶卷和曝光（包含坐标）");
        }catch(Exception e){toast("导出失败，请重新选择位置");}
    }
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    private void fatal(){new AlertDialog.Builder(this).setTitle("无法打开本地记录").setMessage("没有清除数据。请检查存储空间后重试。").setPositiveButton("关闭",(d,w)->finish()).setCancelable(false).show();}
